arguments.command:
cd /tmp/vally-eval-trial-YJB6JN && export PATH=/tmp/pb:$PATH PYTHONPATH=$PWD/src:$PWD/.venv/lib/python3.12/site-packages PYTHONDONTWRITEBYTECODE=1 && rm -f /tmp/core.sqlite && python -m cosmic_ray.cli init cosmic-ray-core.toml /tmp/core.sqlite && python -m cosmic_ray.cli baseline cosmic-ray-core.toml 2>&1 | tail -3; timeout 500 python -m cosmic_ray.cli exec cosmic-ray-core.toml /tmp/core.sqlite 2>&1 | tail -3; python -m cosmic_ray.cli dump /tmp/core.sqlite | python -c "
